// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 등급 및 뱃지 (19번)" (8afd33f52c3d486a8ea882836f91447a).
// REQ-MYPAGE-005 (#31): A안 — 등급은 채택된 답변 수 기준, 뱃지 6종, 조회할 때 계산 (docs/api.md 3장).
// 시안의 활동 점수·점수 획득 기준·상위 %·획득일·등급 혜택은 A안에 없어서 뺐다. 헤더는 공통 components/Header.
// #190: docs/ui-guide.md 공통 값(uiStyles, GradeIcon, BadgeIcon, ListStatus, writer)으로 바꿨다.
import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { getErrorMessage } from "../api/client";
import { getMyGrade, type Badge, type Grade, type GradeInfo } from "../api/mypage";
import BadgeIcon from "../components/BadgeIcon";
import { GRADE_ORDER, GRADES, gradeLevel } from "../components/gradeBadge";
import GradeIcon from "../components/GradeIcon";
import Header from "../components/Header";
import ListStatus from "../components/ListStatus";
import { buttonClass, CARD, FOCUS, NOTICE, PAGE_BACKGROUND, TABLE, tabCountClass } from "../components/uiStyles";
import { formatNumber } from "../components/writer";
import { useAuth } from "../hooks/useAuth";
import { usePageTitle } from "../hooks/usePageTitle";
import "./GradesBadges.css";

const ICON = "material-symbols-outlined text-[18px] leading-none shrink-0";
const CARD_PADDING = "p-4 sm:p-6";
const SECTION_TITLE = "flex items-center gap-1.5 text-lg font-extrabold text-devin-ink";

function percent(current: number, target: number) {
  return Math.min(100, Math.round((current / target) * 1000) / 10);
}

function ProgressBar({ value, label }: { value: number; label: string }) {
  return (
    <div
      className="w-full h-3 rounded-full bg-devin-tag border-[1.5px] border-devin-ink overflow-hidden"
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={value}
    >
      <div className="h-full bg-devin-blue transition-all" data-field="progressBar" style={{ width: `${value}%` }} />
    </div>
  );
}

// 현재 등급 요약 카드: 게이지 = acceptedCount / nextGradeMin
function SummaryCard({ info }: { info: GradeInfo }) {
  const isMax = info.nextGrade === null || info.nextGradeMin === null;
  const progress = isMax ? 100 : percent(info.acceptedCount, info.nextGradeMin as number);
  return (
    <section className={`${CARD} ${CARD_PADDING}`} data-purpose="current-rank-summary">
      <div className="flex flex-col sm:flex-row items-center gap-6">
        {/* 큰 메달: 등급 색은 금속 색 예외 (ui-guide.md 7절) */}
        <div className="relative shrink-0">
          <div className="w-24 h-24 rounded-full bg-devin-bg border-devin border-devin-ink shadow-devin-sm flex items-center justify-center">
            <span
              className="material-symbols-outlined text-[56px] leading-none"
              style={{ color: GRADES[info.grade].color, fontVariationSettings: "'FILL' 1" }}
              aria-hidden="true"
            >
              workspace_premium
            </span>
          </div>
          <span className={`${tabCountClass(false)} absolute -bottom-1 -right-1`} data-field="level">
            LV.{gradeLevel(info.grade)}
          </span>
        </div>

        <div className="flex-1 w-full space-y-3">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h2 className="flex items-center gap-2 text-lg font-extrabold">
              현재 등급
              <span data-field="gradeName">
                <GradeIcon grade={info.grade} withLabel />
              </span>
            </h2>
            <p className="text-sm font-bold text-devin-gray">
              채택된 답변{" "}
              <span className="text-base font-black text-devin-ink tabular-nums" data-field="acceptedCount">
                {formatNumber(info.acceptedCount)}개
              </span>
            </p>
          </div>

          <div className="space-y-1.5" data-purpose="level-progress-bar">
            <div className="flex justify-between items-center text-xs font-bold text-devin-gray">
              <span data-field="progressText">{isMax ? "최고 등급이에요" : `다음 등급까지 ${progress}%`}</span>
              <span className="text-devin-ink font-extrabold tabular-nums" data-field="progressCount">
                {isMax ? `${formatNumber(info.acceptedCount)}개` : `${info.acceptedCount} / ${info.nextGradeMin}`}
              </span>
            </div>
            <ProgressBar value={progress} label="다음 등급까지 진행도" />
          </div>

          <p className={NOTICE.info} data-field="remain">
            <span className={ICON} aria-hidden="true">
              info
            </span>
            {isMax ? (
              <span>가장 높은 등급이에요. 앞으로도 좋은 답변 부탁드려요!</span>
            ) : (
              <span>
                {`다음 등급(${GRADES[info.nextGrade as Grade].label})까지 채택 `}
                <strong className="tabular-nums">{(info.nextGradeMin as number) - info.acceptedCount}개</strong>
                {" 남았어요."}
              </span>
            )}
          </p>
        </div>
      </div>
    </section>
  );
}

// 등급 안내 표: 지금 등급 줄을 크림 바탕 + "현재" 표시로 구분한다. 시안의 "혜택 예시" 칸은 기능이 없어 뺐다.
function GradeTable({ current }: { current: Grade }) {
  return (
    <section className={`${CARD} ${CARD_PADDING}`} data-purpose="grade-info-table-card">
      <h2 className={`${SECTION_TITLE} mb-4`}>
        <span className="material-symbols-outlined text-[20px] leading-none" aria-hidden="true">
          military_tech
        </span>
        등급 안내
      </h2>
      <div className={TABLE.wrap}>
        <table className={TABLE.table} id="grade-table">
          <thead>
            <tr>
              <th className={TABLE.th}>등급</th>
              <th className={`${TABLE.th} ${TABLE.num}`}>필요한 채택 수</th>
            </tr>
          </thead>
          <tbody>
            {GRADE_ORDER.map((grade) => {
              const isCurrent = grade === current;
              return (
                <tr
                  className={`${TABLE.tr} ${isCurrent ? "bg-devin-bg font-bold" : ""}`}
                  aria-current={isCurrent ? "true" : undefined}
                  data-current={isCurrent}
                  key={grade}
                >
                  <td className={TABLE.td}>
                    <span className="inline-flex items-center gap-2">
                      <GradeIcon grade={grade} withLabel />
                      {isCurrent && <span className={tabCountClass(false)}>현재</span>}
                    </span>
                  </td>
                  <td className={`${TABLE.td} ${TABLE.num}`}>채택 {GRADES[grade].minAccepted}개 이상</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </section>
  );
}

// 뱃지 상세: 획득 조건과 진행도 (REQ-MYPAGE-005 "뱃지 클릭 시 획득 조건 표시")
function BadgeDetail({ badge, onClose }: { badge: Badge; onClose: () => void }) {
  return (
    <div
      className="lg:col-span-5 p-4 rounded-xl border-devin border-devin-ink bg-devin-paper space-y-4"
      data-purpose="badge-detail-modal-card"
    >
      <div className="flex items-center gap-4">
        <BadgeIcon code={badge.code} acquired={badge.acquired} size="lg" />
        <div className="space-y-1">
          <h3 className="text-base font-extrabold" data-field="detailName">
            {badge.name}
          </h3>
          <p
            className={`flex items-center gap-1 text-xs font-bold ${badge.acquired ? "text-devin-ink" : "text-devin-gray"}`}
          >
            <span className="material-symbols-outlined text-[15px] leading-none" aria-hidden="true">
              {badge.acquired ? "check_circle" : "lock"}
            </span>
            {badge.acquired ? "획득했어요" : "아직 얻지 못했어요"}
          </p>
        </div>
      </div>
      <div className="p-4 rounded-lg bg-devin-bg space-y-2">
        <p className="text-xs font-bold" data-field="detailCondition">
          획득 조건: {badge.condition}
        </p>
        <div>
          <div className="flex justify-between mb-1 text-[11px] font-bold text-devin-gray">
            <span>진행도</span>
            <span className="tabular-nums" data-field="detailProgress">
              {Math.min(badge.current, badge.target)} / {badge.target}
            </span>
          </div>
          <ProgressBar value={percent(badge.current, badge.target)} label={`${badge.name} 진행도`} />
        </div>
      </div>
      <div className="flex justify-end">
        <button className={buttonClass("secondary", "sm")} onClick={onClose} type="button">
          닫기
        </button>
      </div>
    </div>
  );
}

function BadgeSection({ badges }: { badges: Badge[] }) {
  const [selected, setSelected] = useState<Badge | null>(null);
  const acquired = badges.filter((b) => b.acquired).length;
  return (
    <section className={`${CARD} ${CARD_PADDING}`} data-purpose="badges-container">
      <div className="flex flex-wrap items-center justify-between gap-2 pb-3 mb-6 border-b-2 border-devin-line">
        <h2 className={SECTION_TITLE}>
          뱃지 목록
          <span className={tabCountClass(false)} data-field="badgeCount">
            {acquired}/{badges.length}
          </span>
        </h2>
        <span className="text-xs text-devin-gray">뱃지를 누르면 획득 조건을 볼 수 있어요.</span>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        <div className="lg:col-span-7 grid grid-cols-3 gap-y-6 gap-x-3 text-center" data-purpose="badge-icons-grid">
          {badges.map((badge) => {
            const isSelected = selected?.code === badge.code;
            return (
              <button
                aria-pressed={isSelected}
                className={`flex flex-col items-center gap-2 p-1 rounded-xl group ${FOCUS} ${
                  isSelected ? "bg-devin-bg" : ""
                }`}
                data-acquired={badge.acquired}
                data-code={badge.code}
                key={badge.code}
                onClick={() => setSelected(isSelected ? null : badge)}
                type="button"
              >
                <span className="rounded-full group-hover:-translate-y-0.5 transition-transform">
                  <BadgeIcon code={badge.code} acquired={badge.acquired} />
                </span>
                <span
                  className={`text-xs ${
                    isSelected
                      ? "font-black text-devin-ink underline underline-offset-2"
                      : badge.acquired
                        ? "font-bold text-devin-ink"
                        : "font-medium text-devin-gray-light"
                  }`}
                >
                  {badge.name}
                </span>
              </button>
            );
          })}
        </div>

        {selected ? (
          <BadgeDetail badge={selected} onClose={() => setSelected(null)} />
        ) : (
          <div className="lg:col-span-5 flex flex-col items-center gap-2 p-6 rounded-xl border-devin border-dashed border-devin-gray-light text-center text-sm font-semibold text-devin-gray">
            <span className="material-symbols-outlined text-[28px] leading-none" aria-hidden="true">
              touch_app
            </span>
            뱃지를 고르면 획득 조건과 진행도가 여기에 보여요.
          </div>
        )}
      </div>
    </section>
  );
}

export default function GradesBadges() {
  usePageTitle("등급 및 뱃지");
  const navigate = useNavigate();
  const { user, initializing } = useAuth();
  const [info, setInfo] = useState<GradeInfo | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);

  // 로그인이 필요한 화면이다. 새로고침 직후에는 reissue로 로그인 상태를 복구할 때까지 기다린다.
  useEffect(() => {
    if (!initializing && !user) {
      navigate("/login", { replace: true });
    }
  }, [initializing, user, navigate]);

  const loggedIn = user !== null;
  useEffect(() => {
    if (!loggedIn) return;
    let cancelled = false;
    getMyGrade()
      .then((result) => {
        if (!cancelled) setInfo(result);
      })
      .catch((error) => {
        if (!cancelled)
          setLoadError(getErrorMessage(error, "등급 정보를 불러오지 못했어요. 잠시 후 다시 시도해 주세요."));
      });
    return () => {
      cancelled = true;
    };
  }, [loggedIn]);

  return (
    <div id="page-grades-badges">
      <div className={`${PAGE_BACKGROUND} text-devin-ink min-h-screen flex flex-col antialiased`}>
        <Header />
        <main className="w-full max-w-6xl mx-auto px-4 sm:px-6 py-6 space-y-6" data-purpose="page-wrapper">
          <header className="flex flex-wrap items-center justify-between gap-3" data-purpose="top-navigation-header">
            <h1 className="text-2xl font-black">등급 및 뱃지</h1>
            <Link className={buttonClass("secondary", "sm")} to="/mypage">
              <span className={ICON} aria-hidden="true">
                arrow_back
              </span>
              마이페이지
            </Link>
          </header>

          {loadError && (
            <p className={NOTICE.error} role="alert">
              <span className={ICON} aria-hidden="true">
                error
              </span>
              {loadError}
            </p>
          )}
          {!info && !loadError && <ListStatus kind="loading">등급 정보를 불러오는 중이에요.</ListStatus>}

          {info && (
            <>
              <SummaryCard info={info} />
              <GradeTable current={info.grade} />
              <BadgeSection badges={info.badges} />
            </>
          )}
        </main>
      </div>
    </div>
  );
}
